static Scene Scene(){var s=SceneManager.GetSceneByPath("Assets/ArtStyleTest/Scenes/out.unity");if(!s.isLoaded||EditorApplication.isPlaying)throw new Exception("Open out in Edit mode");return s;}
static string Path(Transform t){return t.parent?Path(t.parent)+"/"+t.name:t.name;}
static Camera View(Scene s){return s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai");}
static Vector3 Head=new Vector3(Mathf.Sin(.94f*2.2f)*.022f,.94f,.94f*.94f*.018f);
static readonly Vector2[] Spots={new Vector2(.33f,.25f),new Vector2(.59f,.24f),new Vector2(.69f,.17f),new Vector2(.815f,.18f),new Vector2(.845f,.075f)};
static MethodInfo Intersect=typeof(HandleUtility).GetMethod("IntersectRayMesh",BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic);
static MeshRenderer[] Grounds(Scene s){return s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(false)).Where(r=>r.enabled&&r.GetComponent<MeshFilter>()?.sharedMesh&&((r.name=="Cube"&&r.transform.parent&&r.transform.parent.name=="xiangjipingtai")||(!Path(r.transform).Contains("grass")&&r.sharedMaterials.Any(m=>m&&m.shader&&(m.shader.name=="Codex/PainterlyMeadow/Ground"||m.shader.name=="ArtStyleTest/DetailedMeadowLit"))))).ToArray();}
static Ray Ray(Camera c,Vector2 uv){float aspect=c.aspect;try{c.aspect=16f/9;return c.ViewportPointToRay(uv);}finally{c.aspect=aspect;}}
static bool Ground(Scene s,Ray ray,MeshRenderer[] grounds,out RaycastHit nearest){nearest=new RaycastHit();float best=1e6f;foreach(var r in grounds){object[] args={ray,r.GetComponent<MeshFilter>().sharedMesh,r.localToWorldMatrix,new RaycastHit()};if((bool)Intersect.Invoke(null,args)){var hit=(RaycastHit)args[3];if(hit.normal.y>.2f&&hit.distance<best){best=hit.distance;nearest=hit;}}}foreach(var t in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Terrain>(false)).Where(t=>t.enabled&&t.drawHeightmap)){RaycastHit hit;var collider=t.GetComponent<TerrainCollider>();if(collider&&collider.Raycast(ray,out hit,200)&&hit.normal.y>.2f&&hit.distance<best){best=hit.distance;nearest=hit;}}return best<1e6f;}
static MeshRenderer[] City(Scene s){return s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(false)).Where(r=>r.enabled&&Path(r.transform).Contains("04 - Lost city and broken viaduct")&&r.GetComponent<MeshFilter>()?.sharedMesh).ToArray();}
[MenuItem("Tools/Out Scene Transfer/Inspect Flower Layout And Distant Turf")]
public static void Inspect(){var b=new StringBuilder();try{var s=Scene();var camera=View(s);string backup="Assets/ArtStyleTest/Scenes_BACKUP/out_before_flower_layout_turf_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity";if(!EditorSceneManager.SaveScene(s,backup,true))throw new Exception("Backup failed");b.AppendLine("backup="+backup);foreach(var f in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(false)).Where(f=>f.name.StartsWith("Daisy_")))b.AppendLine("flower="+f.name+" head="+camera.WorldToViewportPoint(f.transform.TransformPoint(Head))+" position="+f.transform.position);var grounds=Grounds(s);foreach(var r in grounds)b.AppendLine("ground="+Path(r.transform));foreach(var uv in Spots){RaycastHit hit;b.AppendLine("spot="+uv+" hit="+Ground(s,Ray(camera,uv),grounds,out hit)+" point="+hit.point+" normal="+hit.normal);}foreach(var r in City(s)){b.AppendLine("city="+Path(r.transform)+" bounds="+r.bounds+" mesh="+r.GetComponent<MeshFilter>().sharedMesh.name+" shader="+r.sharedMaterial.shader.name);if(r.sharedMaterial.HasProperty("_BaseColor"))b.AppendLine("baseColor="+r.sharedMaterial.GetColor("_BaseColor"));}b.AppendLine("backedUp=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_flower_turf_inspect.txt",b.ToString());}
sealed class Build {public List<Vector3> v=new List<Vector3>(),n=new List<Vector3>();public List<Color> c=new List<Color>();public List<Vector4> uv=new List<Vector4>();public void Add(Vector3 p,Vector3 normal,Color colour,Vector4 tex){v.Add(p);n.Add(normal);c.Add(colour);uv.Add(tex);}public Mesh Mesh(string name,Vector3 origin){var m=new Mesh{name=name,indexFormat=IndexFormat.UInt32};m.SetVertices(v.Select(p=>p-origin).ToList());m.SetNormals(n);m.SetColors(c);m.SetUVs(0,uv);m.SetTriangles(Enumerable.Range(0,v.Count).ToArray(),0);m.RecalculateBounds();return m;}}
static MeshRenderer Render(Build build,Transform parent,string name,Material material,string asset,Vector3 origin){var mesh=build.Mesh(name,origin);AssetDatabase.CreateAsset(mesh,asset);var g=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(parent,false);g.GetComponent<MeshFilter>().sharedMesh=mesh;var r=g.GetComponent<MeshRenderer>();r.sharedMaterial=material;r.shadowCastingMode=ShadowCastingMode.Off;return r;}
static int SplitRoof(Transform grass,StringBuilder report){var binding=grass.GetComponentsInChildren<SurfaceGrassBinding>(true).First(b=>b.surface&&b.surface.name.Contains("Mossy_Dome"));if(binding.transform.Find("可编辑苔草片"))throw new Exception("Roof already split");var old=binding.GetComponentsInChildren<MeshFilter>(false);var groups=new Dictionary<Vector3Int,Dictionary<string,Build>>();var mats=new Dictionary<string,Material>();foreach(var f in old){var mesh=f.sharedMesh;var vs=mesh.vertices;var ns=mesh.normals;var cs=mesh.colors;var uvs=new List<Vector4>();mesh.GetUVs(0,uvs);var tris=mesh.triangles;string kind=f.name;mats[kind]=f.GetComponent<MeshRenderer>().sharedMaterial;for(int t=0;t<tris.Length;t+=3){var center=(vs[tris[t]]+vs[tris[t+1]]+vs[tris[t+2]])/3;var key=new Vector3Int(Mathf.FloorToInt(center.x/1.5f),Mathf.FloorToInt(center.y/1.5f),Mathf.FloorToInt(center.z/1.5f));if(!groups.ContainsKey(key))groups[key]=new Dictionary<string,Build>();if(!groups[key].ContainsKey(kind))groups[key][kind]=new Build();var build=groups[key][kind];for(int j=0;j<3;j++){int i=tris[t+j];build.Add(vs[i],ns[i],cs[i],uvs[i]);}}}var parent=new GameObject("可编辑苔草片");parent.transform.SetParent(binding.transform,false);int index=0;foreach(var pair in groups){var all=pair.Value.Values.SelectMany(b=>b.v).ToArray();var bounds=new Bounds(all[0],Vector3.zero);foreach(var p in all)bounds.Encapsulate(p);var patch=new GameObject("苔草片_"+(++index).ToString("00"));patch.transform.SetParent(parent.transform,false);patch.transform.localPosition=bounds.center;foreach(var part in pair.Value){var origin=bounds.center;var mesh=part.Value.Mesh(patch.name+"_"+part.Key,origin);if(part.Key=="Short_Grass"){var uv=new List<Vector4>();mesh.GetUVs(0,uv);for(int i=0;i<uv.Count;i++)uv[i]=new Vector4(uv[i].x-origin.x,uv[i].y-origin.y,uv[i].z-origin.z,uv[i].w);mesh.SetUVs(0,uv);}string path=A+"/EditableRoof/"+patch.name+"_"+part.Key+".asset";AssetDatabase.CreateAsset(mesh,path);var child=new GameObject(part.Key,typeof(MeshFilter),typeof(MeshRenderer));child.transform.SetParent(patch.transform,false);child.GetComponent<MeshFilter>().sharedMesh=mesh;child.GetComponent<MeshRenderer>().sharedMaterial=mats[part.Key];child.GetComponent<MeshRenderer>().shadowCastingMode=ShadowCastingMode.Off;}}
foreach(var f in old)Undo.DestroyObjectImmediate(f.gameObject);report.AppendLine("editableRoofPatches="+index+" centeredPivots=True combinedMossAndShortGrass=True");return index;}
static int Flowers(Scene s,Transform grass,Camera camera,StringBuilder report){var flowers=grass.GetComponentsInChildren<MeshFilter>(false).Where(f=>f.name.StartsWith("Daisy_")).OrderBy(f=>f.name).ToArray();var keep=new HashSet<string>(new[]{"Daisy_01","Daisy_02","Daisy_03","Daisy_04","Daisy_07","Daisy_08","Daisy_15","Daisy_20","Daisy_21","Daisy_23","Daisy_25","Daisy_30"});var move=flowers.Where(f=>!keep.Contains(f.name)).ToArray();var grounds=Grounds(s);var rng=new System.Random(19424);int count=0;for(int k=0;k<move.Length;k++){var f=move[k];int cluster=k%Spots.Length;int member=k/Spots.Length;Vector2[] shifts={new Vector2(-.018f,-.006f),new Vector2(.008f,.004f),new Vector2(.023f,-.015f),new Vector2(-.003f,.023f)};var uv=Spots[cluster]+shifts[member];RaycastHit hit;var rootRay=Ray(camera,uv);rootRay.origin-=Vector3.up*1.06f;if(!Ground(s,rootRay,grounds,out hit))throw new Exception("Missing foreground ground "+uv);Undo.RecordObject(f.transform,"Redistribute flowers into foreground");f.transform.position=hit.point+hit.normal*.008f;f.transform.rotation=Quaternion.FromToRotation(Vector3.up,Vector3.Lerp(Vector3.up,hit.normal,.15f))*Quaternion.Euler(0,(float)rng.NextDouble()*360,0);float height=.95f+(float)rng.NextDouble()*.18f;f.transform.localScale=Vector3.one*height;EditorUtility.SetDirty(f.transform);count++;report.AppendLine("moved="+f.name+" cluster="+(cluster+1)+" root="+hit.point);}
var source=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/ArtStyleTest/OutAssets/Codex_PainterlyMeadow/Flowers/Small_Meadow_Daisy.asset");foreach(var f in move){var vs=source.vertices;var ns=source.normals;float depth=camera.WorldToViewportPoint(f.transform.TransformPoint(Head)).z;float diameter=Mathf.Clamp(18*2*Mathf.Tan(camera.fieldOfView*Mathf.Deg2Rad*.5f)*depth/900,.12f,.30f);var toward=(camera.transform.position-f.transform.TransformPoint(Head)).normalized;var rotation=Quaternion.FromToRotation(new Vector3(.12f,.94f,-.32f).normalized,Vector3.Lerp(Vector3.up,toward,.72f).normalized);for(int i=33;i<vs.Length;i++){vs[i]=Head+f.transform.InverseTransformVector(rotation*((vs[i]-Head)*(diameter/.096f)));ns[i]=f.transform.localToWorldMatrix.transpose.MultiplyVector(rotation*ns[i]).normalized;}Undo.RecordObject(f.sharedMesh,"Resize moved flower heads for foreground");f.sharedMesh.vertices=vs;f.sharedMesh.normals=ns;f.sharedMesh.RecalculateBounds();EditorUtility.SetDirty(f.sharedMesh);}report.AppendLine("foregroundFlowers="+count+" keptFlowers="+keep.Count+" foregroundClusters=5");return count;}
sealed class Turf {public Build build=new Build();public MeshRenderer source;public float Mask(Vector3 p,Vector3 n){var b=source.bounds;float height=Mathf.InverseLerp(b.min.y,b.max.y,p.y);float column=Mathf.PerlinNoise(p.x*.50f+21,p.z*.50f+8);float patches=Mathf.PerlinNoise(p.x*.75f+p.y*.13f+14,p.z*.75f+p.y*.10f+38);float noise=column*.55f+patches*.45f;float threshold=n.y>.45f?.41f:Mathf.Lerp(.68f,.47f,Mathf.Pow(height,2));return Mathf.Clamp01(.5f+(noise-threshold)*4);}
public void Tri(Vector3 a,Vector3 b,Vector3 c,Vector3 na,Vector3 nb,Vector3 nc,int depth){if(Mathf.Max(na.y,Mathf.Max(nb.y,nc.y))<-.35f)return;if(depth<7&&Mathf.Max((a-b).magnitude,Mathf.Max((a-c).magnitude,(b-c).magnitude))>.40f){var ab=(a+b)*.5f;var ac=(a+c)*.5f;var bc=(b+c)*.5f;var nab=(na+nb).normalized;var nac=(na+nc).normalized;var nbc=(nb+nc).normalized;Tri(a,ab,ac,na,nab,nac,depth+1);Tri(ab,b,bc,nab,nb,nbc,depth+1);Tri(ac,bc,c,nac,nbc,nc,depth+1);Tri(ab,bc,ac,nab,nbc,nac,depth+1);return;}var ps=new[]{a,b,c};var ns=new[]{na,nb,nc};var masks=ps.Select((p,i)=>Mask(p,ns[i])).ToArray();if(masks.Max()<.5f)return;for(int i=0;i<3;i++){var p=ps[i]+ns[i]*.025f;var normal=source.localToWorldMatrix.transpose.MultiplyVector(ns[i]).normalized;build.Add(source.transform.InverseTransformPoint(p),normal,new Color(Mathf.PerlinNoise(p.x*.7f,p.z*.7f),1,1,masks[i]),Vector4.zero);}}
public void Make(){var m=source.GetComponent<MeshFilter>().sharedMesh;var vs=m.vertices;var ns=m.normals;var ts=m.triangles;var matrix=source.localToWorldMatrix;var nm=matrix.inverse.transpose;for(int i=0;i<ts.Length;i+=3){int a=ts[i],b=ts[i+1],c=ts[i+2];Tri(matrix.MultiplyPoint3x4(vs[a]),matrix.MultiplyPoint3x4(vs[b]),matrix.MultiplyPoint3x4(vs[c]),nm.MultiplyVector(ns[a]).normalized,nm.MultiplyVector(ns[b]).normalized,nm.MultiplyVector(ns[c]).normalized,0);}}}
static int Distant(Scene s,Transform grass,StringBuilder report){if(grass.Find("远景建筑草皮"))throw new Exception("Distant turf exists");var root=new GameObject("远景建筑草皮");root.transform.SetParent(grass,false);var material=new Material(Shader.Find("Codex/Meadow/DistantTurf")){name="Distant muted green turf"};AssetDatabase.CreateAsset(material,A+"/Materials/Distant_Turf.mat");int count=0;foreach(var r in City(s)){var turf=new Turf{source=r};turf.Make();if(turf.build.v.Count==0)continue;var g=new GameObject(r.transform.parent.name+" - "+r.name+" - 草皮");g.transform.SetParent(root.transform,false);var binding=g.AddComponent<SurfaceGrassBinding>();binding.surface=r.transform;binding.Apply();Render(turf.build,g.transform,"绿色草皮",material,A+"/DistantTurf/"+(++count).ToString("D3")+".asset",Vector3.zero);}report.AppendLine("distantTurfSurfaces="+count+" individualBlades=0");return count;}
[MenuItem("Tools/Out Scene Transfer/Finalize Flower Turf Layout And Editable Groups")]
public static void FinalizeLayout(){var b=new StringBuilder();try{var s=Scene();var c=View(s);var grass=s.GetRootGameObjects().First(g=>g.name=="grass").transform;Flowers(s,grass,c,b);var roof=grass.GetComponentsInChildren<SurfaceGrassBinding>(true).First(x=>x.surface&&x.surface.name.Contains("Mossy_Dome"));Undo.SetTransformParent(roof.transform,grass,"Organize editable house grass");roof.name="房屋苔草";EditorUtility.SetDirty(roof);int errors=0;foreach(var shader in grass.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Where(m=>m).Select(m=>m.shader).Distinct())foreach(var error in ShaderUtil.GetShaderMessages(shader).Where(m=>m.severity.ToString()=="Error")){errors++;b.AppendLine(error.message);}if(errors>0)throw new Exception("Shader errors");foreach(Transform patch in roof.transform.Find("可编辑苔草片")){if(patch.GetComponentsInChildren<MeshFilter>().Length==0||patch.GetComponent<SurfaceGrassBinding>())throw new Exception("Patch cannot edit independently");}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);typeof(OutReferenceComposition).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{c,O+"Out_foreground_flowers_editable_roof_distant_turf.png"});Selection.activeGameObject=roof.transform.Find("可编辑苔草片").GetChild(0).gameObject;EditorGUIUtility.PingObject(Selection.activeGameObject);b.AppendLine("shaderErrors="+errors+" editableRoofPatches="+roof.transform.Find("可编辑苔草片").childCount+" saved=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_flower_turf_final.txt",b.ToString());}
[MenuItem("Tools/Out Scene Transfer/Apply Foreground Flowers Editable Roof And Distant Turf")]
public static void Apply(){var report=new StringBuilder();try{if(!File.ReadAllText(W+"out_flower_turf_inspect.txt").Contains("backedUp=True"))throw new Exception("Backup missing");var s=Scene();var camera=View(s);var grass=s.GetRootGameObjects().First(g=>g.name=="grass").transform;var original=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>!t.name.StartsWith("Daisy_")).ToDictionary(t=>t,t=>t.localToWorldMatrix);var lights=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Light>(true)).ToDictionary(l=>l,l=>EditorJsonUtility.ToJson(l));string cameraState=EditorJsonUtility.ToJson(camera);foreach(var d in new[]{"EditableRoof","DistantTurf"})Directory.CreateDirectory(A+"/"+d);AssetDatabase.Refresh();Flowers(s,grass,camera,report);SplitRoof(grass,report);Distant(s,grass,report);foreach(var item in original){if(!item.Key)continue;for(int i=0;i<16;i++)if(Mathf.Abs(item.Key.localToWorldMatrix[i]-item.Value[i])>.002f)throw new Exception("Unexpected movement "+item.Key.name);}foreach(var l in lights)if(EditorJsonUtility.ToJson(l.Key)!=l.Value)throw new Exception("Light changed");if(EditorJsonUtility.ToJson(camera)!=cameraState)throw new Exception("Camera changed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);typeof(OutReferenceComposition).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{camera,O+"Out_foreground_flowers_editable_roof_distant_turf.png"});Selection.activeGameObject=grass.gameObject;report.AppendLine("cameraLightsOtherTransformsUnchanged=True saved=True");}catch(Exception e){report.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_flower_turf_result.txt",report.ToString());}
